// ===========================================================================
// ported from: src/executionCase/canonical.ts
// ===========================================================================

export function canonicalize(value) {
  if (value === null || typeof value === 'number' || typeof value === 'boolean') {
    return JSON.stringify(value);
  }
  if (typeof value === 'string') return JSON.stringify(value);
  if (Array.isArray(value)) {
    return `[${value.map(canonicalize).join(',')}]`;
  }
  if (typeof value === 'object') {
    const entries = Object.entries(value)
      .filter(([, v]) => v !== undefined)
      .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
    return `{${entries.map(([k, v]) => `${JSON.stringify(k)}:${canonicalize(v)}`).join(',')}}`;
  }
  throw new Error(`unsupported value in canonical form: ${typeof value}`);
}

export function sha3Bytes(data) {
  const buf = typeof data === 'string' ? Buffer.from(data, 'utf8') : Buffer.from(data);
  return createHash('sha3-256').update(buf).digest();
}

export function sha3Hex(data) {
  return '0x' + sha3Bytes(data).toString('hex');
}

export function canonicalHash(value) {
  return sha3Hex(canonicalize(value));
}

// ===========================================================================
// ported from: src/executionCase/keys.ts (verifyBytes only — the verifier
// never signs and never touches key files)
// ===========================================================================

const SPKI_ED25519_PREFIX = Buffer.from('302a300506032b6570032100', 'hex');

export function verifyBytes(publicKeyHex, data, signatureHex) {
  if (!/^[0-9a-f]{64}$/.test(publicKeyHex) || !/^[0-9a-f]{128}$/.test(signatureHex)) return false;
  try {
    const pub = createPublicKey({
      key: Buffer.concat([SPKI_ED25519_PREFIX, Buffer.from(publicKeyHex, 'hex')]),
      format: 'der',
      type: 'spki',
    });
    return edVerify(null, Buffer.from(data), pub, Buffer.from(signatureHex, 'hex'));
  } catch {
    return false;
  }
}

// ===========================================================================
// ported from: src/executionCase/journal.ts (scanJournal only)
// ===========================================================================

export const GENESIS_HASH = '0x' + '0'.repeat(64);

export function scanJournal(path) {
  if (!existsSync(path)) return { ok: true, lines: 0, head: GENESIS_HASH, entries: [] };
  const raw = readFileSync(path, 'utf8');
  const lines = raw.split('\n').filter((l) => l.length > 0);
  const entries = [];
  let prev = GENESIS_HASH;
  for (let i = 0; i < lines.length; i++) {
    let parsed;
    try {
      parsed = JSON.parse(lines[i]);
    } catch (err) {
      return { ok: false, lines: i, head: prev, entries, firstBad: i + 1, error: `unparseable line: ${String(err)}` };
    }
    if (canonicalize(parsed) !== lines[i]) {
      return { ok: false, lines: i, head: prev, entries, firstBad: i + 1, error: 'line is not in canonical form' };
    }
    if (parsed.prev_hash !== prev) {
      return { ok: false, lines: i, head: prev, entries, firstBad: i + 1, error: 'prev_hash mismatch' };
    }
    prev = sha3Hex(lines[i]);
    entries.push(parsed);
  }
  return { ok: true, lines: lines.length, head: prev, entries };
}

// ===========================================================================
// ported from: src/executionCase/verifier/verifierShared.ts
