export const MANDATE_SCHEMA = 'cosmo.execution-case.mandate.v2';
export const RECEIPT_SCHEMA = 'cosmo.execution-case.receipt.v2';
export const MANIFEST_SCHEMA = 'cosmo.execution-case.manifest.v1';

// ===========================================================================
// ported from: src/executionCase/evidence.ts (verify-side surface only)
// ===========================================================================

export function evidenceDir(cDir) {
  return join(cDir, 'evidence');
}

export function evidenceRoot(manifest) {
  return canonicalHash(manifest);
}

export const ARTIFACT_FILE = 'artifact.hex';
export const ARTIFACT_VERIFY_FILE = 'artifact-verify.json';

export const CORE_EVIDENCE_BASE = ['intent.json', 'policy.json', 'errors.json'];

export function coreRequiredFiles(outcome) {
  const base = [...CORE_EVIDENCE_BASE];
  switch (outcome) {
    case 'INVALID_INTENT':
      return {
        required: [...base, 'intake-decision.json'],
        forbidden: ['mandate.json', ARTIFACT_FILE, 'submit-result.json'],
      };
    case 'HALTED':
      return { required: base, forbidden: [] };
    default:
      return null;
  }
}

// ===========================================================================
// ported from: src/executionCase/mandate.ts (verify-side surface only)
// ===========================================================================

export const MANDATE_DOMAIN = 'COSMO-EXECUTION-CASE MANDATE v2';

export function mandateMessage(caseId, hash) {
  return Buffer.from(`${MANDATE_DOMAIN}\ncase: ${caseId}\nhash: ${hash}`, 'utf8');
}

export function caseCorrelationId(hash) {
  if (!/^0x[0-9a-f]{64}$/.test(hash)) throw new Error(`malformed mandate hash: ${hash}`);
  return hash.slice(2, 34);
}

// ===========================================================================
// ported from: src/executionCase/receipt.ts (verify-side surface only)
// ===========================================================================

export function loadEvidenceView(cDir) {
  const manifest = JSON.parse(readFileSync(join(cDir, 'MANIFEST.json'), 'utf8'));
  const dir = evidenceDir(cDir);
  const readEvidence = (name) => (manifest.files[name] ? readFileSync(join(dir, name), 'utf8') : null);

  const mandateRaw = readEvidence('mandate.json');
  const intentRaw = readEvidence('intent.json');
  let intentParsed = null;
  try {
    intentParsed = intentRaw ? JSON.parse(intentRaw) : null;
  } catch {
    intentParsed = null; // INVALID_INTENT may carry unparseable intent bytes
  }
  return {
    manifest,
    mandate: mandateRaw ? JSON.parse(mandateRaw) : null,
    intentParsed,
    artifactHex: readEvidence(ARTIFACT_FILE)?.trim() ?? null,
    readEvidence,
  };
}

export function deriveReceiptStatement(view, ctx, domainBlock) {
  const m = view.mandate;
  return {
    schema: RECEIPT_SCHEMA,
    case_id: ctx.case_id,
    outcome: ctx.outcome,
    outcome_detail: ctx.outcome_detail,
    mode: ctx.mode,
    principal_ref: m?.principal_ref ?? view.intentParsed?.principal_ref ?? null,
    agent_ref: m?.agent_ref ?? view.intentParsed?.agent_ref ?? null,
    execution_key_ref: m?.execution_key_ref ?? null,
    mandate_hash: m ? sha3Hex(canonicalize(m)) : null,
    policy_hash: view.manifest.policy_hash,
    execution_ref: view.artifactHex ? sha3Hex(Buffer.from(view.artifactHex, 'hex')) : null,
    evidence_root: evidenceRoot(view.manifest),
    action_kind: m?.action.kind ?? view.intentParsed?.action?.kind ?? null,
    domain: domainBlock,
    created_at: ctx.created_at,
    closed_at: ctx.closed_at,
    context: { producer_commit: ctx.producer_commit, runtime_version: ctx.runtime_version },
  };
}

export function receiptSignedBytes(attestor, attestedAt, statement) {
  return Buffer.from(canonicalize({ envelope: { attestor, attested_at: attestedAt }, statement }), 'utf8');
}

// ===========================================================================
// ported from: src/executionCase/domains/marketWork/order.ts (verify surface)
// ===========================================================================

export const MARKET_ORDER_DOMAIN = 'COSMO-MARKET-DELIVER v1';

export function orderSignBytes(order) {
  return Buffer.from(`${MARKET_ORDER_DOMAIN}\n${canonicalize(order)}`, 'utf8');
}

export function solverAddressFromPubkey(pubkeyHex) {
  const pub = Buffer.from(pubkeyHex, 'hex');
  return '0x' + createHash('sha3-256').update(Buffer.concat([pub, Buffer.from([0x00])])).digest('hex');
}

export function addrEq(a, b) {
  if (!a || !b) return false;
  const norm = (x) => x.replace(/^0x/, '').toLowerCase().replace(/^0+/, '');
  return norm(a) === norm(b);
}

