const marketWorkDomain = {
  kind: MARKET_WORK_KIND,

  deriveDomainBlock(view) {
    const m = view.mandate;
    const p = m ? m.action.params : null;
    const intentP = view.intentParsed ? view.intentParsed.action.params : null;
    const artifactVerifyRaw = view.readEvidence(ARTIFACT_VERIFY_FILE);
    const chain = artifactVerifyRaw ? (JSON.parse(artifactVerifyRaw).chain ?? null) : null;
    let settlementRef = null;
    const obsRaw = view.readEvidence('settlement-observations.jsonl');
    if (obsRaw) {
      for (const line of obsRaw.split('\n').filter(Boolean)) {
        const obs = JSON.parse(line);
        if (obs.confirming && obs.settlement_ref) settlementRef = obs.settlement_ref;
      }
    }
    return {
      job_ref: p?.job_ref ?? intentP?.job_ref ?? null,
      job_id_onchain: p?.job_id_onchain ?? intentP?.job_id_onchain ?? null,
      result_hash: p?.result_hash ?? intentP?.result_hash ?? null,
      result_uri: p?.result_uri ?? intentP?.result_uri ?? null,
      chain,
      settlement_ref: settlementRef,
    };
  },

  requiredFiles(outcome, _mode) {
    const base = [...CORE_EVIDENCE_BASE];
    const policyStage = ['mandate.json', 'mandate.sig.json', 'policy-decision.json', 'job-snapshot.json', 'result-preimage.json'];
    switch (outcome) {
      case 'INVALID_INTENT':
        return { required: [...base, 'intake-decision.json'], forbidden: ['mandate.json', ARTIFACT_FILE, 'submit-result.json'] };
      case 'POLICY_REJECTED':
        return { required: [...base, ...policyStage], forbidden: [ARTIFACT_FILE, 'submit-result.json'] };
      case 'EXPIRED':
        return { required: [...base, 'mandate.json', 'mandate.sig.json'], forbidden: [] };
      case 'HALTED':
        return { required: base, forbidden: [] };
      case 'EXECUTION_FAILED':
        return { required: [...base, 'mandate.json', 'mandate.sig.json'], forbidden: [] };
      case 'SHADOW_COMPLETED':
        return {
          required: [...base, ...policyStage, ARTIFACT_FILE, ARTIFACT_VERIFY_FILE],
          forbidden: ['submit-result.json', 'settlement-observations.jsonl'],
        };
      case 'EXECUTED':
        return {
          required: [...base, ...policyStage, ARTIFACT_FILE, ARTIFACT_VERIFY_FILE, 'arm-consumed.json', 'submit-result.json', 'settlement-observations.jsonl'],
          forbidden: [],
        };
      case 'NO_COUNTERPARTY':
        return { required: base, forbidden: [] };
    }
  },

  allowedOutcomes: ['SHADOW_COMPLETED', 'EXECUTED', 'INVALID_INTENT', 'POLICY_REJECTED', 'EXPIRED', 'HALTED', 'EXECUTION_FAILED'],

  async checkArtifact({ artifactHex, stmt, mandate }) {
    let envelope;
    try {
      envelope = JSON.parse(Buffer.from(artifactHex, 'hex').toString('utf8'));
    } catch (err) {
      return { ok: false, detail: `artifact is not a parseable deliver envelope: ${String(err)}` };
    }
    const { order } = envelope;
    if (!order || order.schema !== 'COSMO-MARKET-DELIVER v1') return { ok: false, detail: 'artifact order schema mismatch' };
    if (!verifyBytes(envelope.signer_pubkey, orderSignBytes(order), envelope.signature)) {
      return { ok: false, detail: 'deliver order signature invalid' };
    }
    if (!addrEq(solverAddressFromPubkey(envelope.signer_pubkey), order.sender_address)) {
      return { ok: false, detail: 'order sender_address does not derive from the signing key' };
    }
    const keyRefAddr = stmt.execution_key_ref?.split(':')[1];
    if (!addrEq(order.sender_address, keyRefAddr)) {
      return { ok: false, detail: 'order sender differs from the mandated execution key' };
    }
    if (mandate) {
      const p = mandate.action.params;
      if (order.job_id_onchain !== p.job_id_onchain) return { ok: false, detail: 'order job_id differs from mandate' };
      if (order.result_hash.toLowerCase() !== p.result_hash.toLowerCase()) {
        return { ok: false, detail: 'order result_hash differs from mandate' };
      }
      if (order.result_uri !== p.result_uri) return { ok: false, detail: 'order result_uri differs from mandate' };
    }
    if (stmt.mandate_hash && order.correlation_id !== caseCorrelationId(stmt.mandate_hash)) {
      return { ok: false, detail: 'order correlation_id not derived from the mandate hash (mandate/artifact unlinked)' };
    }
    return { ok: true };
  },

  checkOutcomeExtensions({ stmt, evidenceDir }) {
    const domain = stmt.domain;
    if (stmt.outcome === 'SHADOW_COMPLETED') {
      if (domain?.settlement_ref != null) return { ok: false, detail: 'SHADOW_COMPLETED must carry settlement_ref null' };
      const artifactVerify = JSON.parse(readFileSync(join(evidenceDir, ARTIFACT_VERIFY_FILE), 'utf8'));
      if (artifactVerify.local_verify?.ok !== true) return { ok: false, detail: 'SHADOW_COMPLETED requires local_verify.ok' };
    }
    if (stmt.outcome === 'EXECUTED') {
      if (domain?.settlement_ref == null) return { ok: false, detail: 'EXECUTED requires a settlement_ref' };
      const submit = JSON.parse(readFileSync(join(evidenceDir, 'submit-result.json'), 'utf8'));
      if (submit.ok !== true) return { ok: false, detail: 'EXECUTED requires submit-result.ok' };
      // OQ30 CLOSED (Rene 2026-08-16): the on-chain result hash MUST be present
      // AND equal the mandated result_hash — a missing hash is a named
      // rejection, not a skipped check. Mirrors marketWork/index.ts.
      if (!domain.result_hash) return { ok: false, detail: 'EXECUTED requires the mandated result_hash in the domain block' };
      const onchain = domain.settlement_ref.result_hash_onchain;
      if (!onchain || onchain.toLowerCase() !== domain.result_hash.toLowerCase()) {
        return { ok: false, detail: onchain ? 'on-chain result hash differs from the mandated result hash' : 'EXECUTED settlement_ref is missing the on-chain result hash' };
      }
    }
    return { ok: true };
  },
};

