// Normative profile hash: canonical sha3-256 over the SETS of active pins.
export function trustProfileHash(profile, profileId) {
  return canonicalHash({
    schema: 'cosmo.standalone-verifier.trust.v1',
    trust_profile_id: profileId,
    policies: Object.keys(profile.policies)
      .filter((k) => profile.policies[k].active)
      .sort(),
    attestors: Object.keys(profile.attestors)
      .filter((k) => profile.attestors[k].active)
      .sort(),
  });
}

export const TRUST_PROFILE_HASH = trustProfileHash(TRUST_PROFILE, TRUST_PROFILE_ID);

// ===========================================================================
// [ADR-001 guardrail 3 / plan 7.3.4] Deterministic layout resolver for FLAT
// published bundles (heros.cloud/evidence/*). It ONLY assigns existing files
// to unique normative roles: never edits bytes, never reconstructs content,
// never normalizes formats, never guesses ambiguous assignments (-> rc 2).
// The staged case layout then runs through the UNCHANGED core verifier.
// ===========================================================================

const CASE_FILES = ['receipt.json', 'MANIFEST.json', 'journal.jsonl'];
// Files a published bundle page may carry that are NOT part of the case:
// the human index pages and the delivered work product referenced by
// result_uri. Anything else unassignable is an rc 2, never a silent skip.
const PUBLICATION_EXTRAS = ['index.html', 'index.txt', 'deliverable.json', 'ARM'];
const SAFE_NAME_RE = /^[A-Za-z0-9._-]{1,64}$/;

export function resolveFlatLayout(bundleDir, stagingRoot) {
  const entries = readdirSync(bundleDir, { withFileTypes: true });
  for (const e of entries) {
    if (!SAFE_NAME_RE.test(e.name) || e.name.includes('..')) {
      throw new Error(`layout resolver: unsafe file name ${JSON.stringify(e.name)} in flat bundle`);
    }
    if (!e.isFile()) {
      throw new Error(`layout resolver: ${e.name} is not a regular file (flat bundles may not contain directories or links)`);
    }
  }
  const names = entries.map((e) => e.name);
  for (const f of CASE_FILES) {
    if (!names.includes(f)) throw new Error(`layout resolver: flat bundle is missing ${f}`);
  }
  let manifest;
  try {
    manifest = JSON.parse(readFileSync(join(bundleDir, 'MANIFEST.json'), 'utf8'));
  } catch (err) {
    throw new Error(`layout resolver: cannot parse MANIFEST.json: ${String(err)}`);
  }
  const manifestNames = Object.keys(manifest.files ?? {});
  for (const n of manifestNames) {
    if (!SAFE_NAME_RE.test(n) || n.includes('..')) {
      throw new Error(`layout resolver: unsafe manifest entry ${JSON.stringify(n)}`);
    }
    if (CASE_FILES.includes(n) || PUBLICATION_EXTRAS.includes(n)) {
      throw new Error(`layout resolver: ambiguous name ${n} (manifest entry collides with a reserved bundle file)`);
    }
  }
  for (const n of names) {
    const role = CASE_FILES.includes(n)
      ? 'case'
      : manifestNames.includes(n)
        ? 'evidence'
        : PUBLICATION_EXTRAS.includes(n)
          ? 'extra'
          : null;
    if (role === null) {
      throw new Error(`layout resolver: unassignable file ${n} in flat bundle (not a case file, not in the manifest, not a known publication extra)`);
    }
  }
  // Materialize the case layout with byte-identical copies.
  const staged = join(stagingRoot, 'case');
  mkdirSync(join(staged, 'evidence'), { recursive: true });
  for (const f of CASE_FILES) writeFileSync(join(staged, f), readFileSync(join(bundleDir, f)));
  for (const n of manifestNames) {
    if (names.includes(n)) writeFileSync(join(staged, 'evidence', n), readFileSync(join(bundleDir, n)));
    // A manifest entry with no file present stays absent — criterion V/P/M
    // reports it exactly like a case-layout bundle with the same gap.
  }
  return staged;
}

// ===========================================================================
// [ADR-001 / plan 7.4] Resource + structure guards. Additive hardening that
// never changes the verdict of a legitimate bundle (all real bundles are
// >300x below the caps); violations are deterministic rc 2 errors.
// ===========================================================================

export const MAX_FILE_BYTES = 1_048_576; // 1 MiB per file
export const MAX_BUNDLE_BYTES = 16_777_216; // 16 MiB per bundle
export const MAX_BUNDLE_FILES = 512;

export function guardBundle(dir) {
  let total = 0;
  let count = 0;
  const walk = (d, depth) => {
    if (depth > 3) throw new Error(`resource guard: directory nesting deeper than 3 at ${d}`);
    for (const e of readdirSync(d, { withFileTypes: true })) {
      count += 1;
      if (count > MAX_BUNDLE_FILES) throw new Error(`resource guard: more than ${MAX_BUNDLE_FILES} entries in bundle`);
      const p = join(d, e.name);
      const st = lstatSync(p);
      if (st.isSymbolicLink()) throw new Error(`resource guard: symlink ${e.name} in bundle`);
      if (st.isDirectory()) {
        walk(p, depth + 1);
      } else if (st.isFile()) {
        if (st.size > MAX_FILE_BYTES) throw new Error(`resource guard: ${e.name} exceeds ${MAX_FILE_BYTES} bytes`);
        total += st.size;
        if (total > MAX_BUNDLE_BYTES) throw new Error(`resource guard: bundle exceeds ${MAX_BUNDLE_BYTES} bytes`);
      } else {
        throw new Error(`resource guard: ${e.name} is not a regular file or directory`);
      }
    }
  };
  walk(dir, 0);
}

// ===========================================================================
// [ADR-001] Bundle entry point: guards -> layout resolution -> core verifier
// with the embedded COSMO trust profile. Library callers doing differential
// testing may call verifyCase/verifyCaseV1/verifyCaseV2 directly with
// injected trust — the CLI never exposes that.
// ===========================================================================

export async function verifyBundle(bundleDir) {
  let staging = null;
  try {
    let st;
    try {
      st = lstatSync(bundleDir);
    } catch (err) {
      return { layout: 'unknown', result: { rc: 2, results: [], error: `cannot open bundle: ${String(err)}` } };
    }
    if (!st.isDirectory()) {
      return { layout: 'unknown', result: { rc: 2, results: [], error: 'bundle path is not a directory' } };
    }
    guardBundle(bundleDir);
    let caseDir = bundleDir;
    let layout = 'case';
    const eDir = join(bundleDir, 'evidence');
    const hasEvidenceDir = existsSync(eDir) && lstatSync(eDir).isDirectory();
    if (!hasEvidenceDir) {
      layout = 'flat';
      staging = mkdtempSync(join(tmpdir(), 'cosmo-verify-'));
      caseDir = resolveFlatLayout(bundleDir, staging);
    } else {
      // Structure guard on the case layout's top-level files (plan 7.4.2).
      for (const f of CASE_FILES) {
        const p = join(caseDir, f);
        if (existsSync(p)) {
          const s = lstatSync(p);
          if (s.isSymbolicLink() || !s.isFile()) {
            return { layout, result: { rc: 2, results: [], error: `structure guard: ${f} is not a regular file` } };
          }
        }
      }
    }
    const result = await verifyCase(caseDir, { trust: TRUST_PROFILE });
    return { layout, result };
  } catch (err) {
    return { layout: 'unknown', result: { rc: 2, results: [], error: String(err) } };
  } finally {
    if (staging) rmSync(staging, { recursive: true, force: true });
  }
}

// ===========================================================================
// CLI
// ===========================================================================

function selfSha3() {
  try {
    return sha3Hex(readFileSync(fileURLToPath(import.meta.url)));
  } catch {
    return null;
  }
}

function printJson(obj) {
  process.stdout.write(JSON.stringify(obj) + '\n');
}

export async function main(argv) {
  const args = argv.filter((a) => a !== '');
  if (args.includes('--version')) {
    printJson({
      name: VERIFIER_NAME,
      version: VERIFIER_VERSION,
      trust_profile_id: TRUST_PROFILE_ID,
      trust_profile_hash: TRUST_PROFILE_HASH,
      source_sha3: selfSha3(),
      node: process.version,
    });
    return 0;
  }
  if (args.includes('--show-trust')) {
    printJson({
      trust_profile_id: TRUST_PROFILE_ID,
      trust_profile_hash: TRUST_PROFILE_HASH,
      profile: TRUST_PROFILE,
      note: 'ACCEPT means: valid under exactly this published COSMO trust profile. There is no trust override (ADR-001).',
    });
    return 0;
  }
  const positional = args.filter((a) => !a.startsWith('--'));
  if (positional.length !== 1) {
    process.stderr.write(
      `usage: node cosmo-verify.mjs <bundle-dir>\n` +
        `       node cosmo-verify.mjs --show-trust | --version\n` +
        `Verifies a COSMO execution-case evidence bundle (case layout or flat\n` +
        `published layout) against the embedded ${TRUST_PROFILE_ID} trust profile.\n` +
        `Exit codes: 0 ACCEPT, 1 REJECT, 2 ERROR.\n`,
    );
    return 2;
  }
  const { layout, result } = await verifyBundle(positional[0]);
  printJson({
    verifier: VERIFIER_NAME,
    version: VERIFIER_VERSION,
    trust_profile_id: TRUST_PROFILE_ID,
    trust_profile_hash: TRUST_PROFILE_HASH,
    bundle: positional[0],
    layout,
    verdict: result.rc === 0 ? 'ACCEPT' : result.rc === 1 ? 'REJECT' : 'ERROR',
    rc: result.rc,
    results: result.results,
    ...(result.error !== undefined ? { error: result.error } : {}),
  });
  return result.rc;
}

const isMain = (() => {
  try {
    return realpathSync(fileURLToPath(import.meta.url)) === realpathSync(process.argv[1]);
  } catch {
    return false;
  }
})();

if (isMain) {
  main(process.argv.slice(2)).then(
    (rc) => process.exit(rc),
    (err) => {
      process.stderr.write(String(err) + '\n');
      process.exit(2);
    },
  );
}
